#!/usr/bin/env bash
set -euo pipefail

# Native sources are generated by Expo prebuild on the macOS build worker.
if [[ "$(uname -s)" != "Darwin" ]]; then
  echo "This script requires macOS and Xcode; use the unsigned-ios EAS profile from Windows." >&2
  exit 1
fi

shopt -s nullglob
workspaces=(ios/*.xcworkspace)
projects=(ios/*.xcodeproj)
if [[ ${#workspaces[@]} -ne 1 || ${#projects[@]} -ne 1 ]]; then
  echo "Expected one generated iOS workspace and one app project." >&2
  exit 1
fi

scheme="$(basename "${projects[0]}" .xcodeproj)"
output_dir="$PWD/dist/ios-unsigned"
archive_path="$output_dir/Noval.xcarchive"
mkdir -p "$output_dir"

xcodebuild \
  -workspace "${workspaces[0]}" \
  -scheme "$scheme" \
  -configuration Release \
  -sdk iphoneos \
  -destination 'generic/platform=iOS' \
  -archivePath "$archive_path" \
  -derivedDataPath "$output_dir/DerivedData" \
  archive \
  CODE_SIGNING_ALLOWED=NO \
  CODE_SIGNING_REQUIRED=NO \
  CODE_SIGN_IDENTITY= \
  DEVELOPMENT_TEAM=

apps=("$archive_path"/Products/Applications/*.app)
if [[ ${#apps[@]} -ne 1 ]]; then
  echo "Archive did not contain exactly one device application." >&2
  exit 1
fi
app_path="${apps[0]}"
executable="$(/usr/libexec/PlistBuddy -c 'Print :CFBundleExecutable' "$app_path/Info.plist")"
xcrun lipo -verify_arch arm64 "$app_path/$executable"
if [[ ! -s "$app_path/main.jsbundle" ]]; then
  echo "Release JavaScript bundle is missing; refusing to package an app requiring Metro." >&2
  exit 1
fi

# mktemp isolates packaging so repeated local builds cannot mix old app bundles.
staging_dir="$(mktemp -d "$output_dir/package.XXXXXX")"
trap 'rm -rf "$staging_dir"' EXIT
mkdir "$staging_dir/Payload"
ditto "$app_path" "$staging_dir/Payload/$(basename "$app_path")"
ditto -c -k --keepParent "$staging_dir/Payload" "$output_dir/Noval-unsigned.ipa"
unzip -t "$output_dir/Noval-unsigned.ipa"
echo "Unsigned IPA: $output_dir/Noval-unsigned.ipa"
echo "Re-sign with your own Apple ID before installing on an iPhone."
